<?php
declare(strict_types=1);require __DIR__.'/auth.php';require __DIR__.'/db.php';$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{$pdo=authDb();try{$stmt=$pdo->prepare('SELECT id,name,password_hash FROM users WHERE login=:login LIMIT 1');$stmt->execute(['login'=>trim((string)($_POST['login']??''))]);$user=$stmt->fetch();if(!$user||!password_verify((string)($_POST['password']??''),$user['password_hash'])){$error='Неверный логин или пароль.';}else{session_regenerate_id(true);$_SESSION['user_id']=(int)$user['id'];$_SESSION['name']=$user['name'];header('Location: private.php');exit;}}catch(PDOException $e){error_log($e->getMessage());$error='Произошла ошибка при выполнении запроса.';}}catch(PDOException $e){error_log($e->getMessage());$error='Невозможно подключиться к MySQL.';}}
?><!doctype html><html lang="ru"><meta charset="utf-8"><body><h1>Вход</h1><?php if($error):?><p><?=e($error)?></p><?php endif?><form method="post"><input name="login" required autocomplete="username"><input name="password" type="password" required autocomplete="current-password"><button>Войти</button></form></body></html>
